import React from "react";
import { Sparkles, RefreshCw, Loader2, Info, Hourglass } from "lucide-react";

export type AiRunStatus = "idle" | "loading" | "done" | "error" | "limited";

export interface AiRunState {
  status: AiRunStatus;
  message?: string;
  /** "Gemini" when generated by the model, "Rule-based" when the server used its deterministic fallback */
  engine?: string;
  at?: string;
}

export const AI_IDLE: AiRunState = { status: "idle" };

/**
 * On-demand AI analysis control. One click = one request. Shows a clear loading state, a kind
 * message when the free limit is reached (429), an error with retry, and what produced the text.
 */
export function AiRunBar({
  title,
  description,
  dataUsed,
  state,
  onRun,
  compact = false
}: {
  title: string;
  description: string;
  dataUsed: string[];
  state: AiRunState;
  onRun: () => void;
  compact?: boolean;
}) {
  const busy = state.status === "loading";
  return (
    <div className={`rounded-2xl border border-[var(--border)] bg-[var(--surface)] ${compact ? "p-4" : "p-5"} space-y-3`}>
      <div className="flex flex-col sm:flex-row sm:items-start justify-between gap-3">
        <div>
          <p className="text-sm font-semibold text-[var(--text)] flex items-center gap-1.5">
            <Sparkles className="h-4 w-4 text-[var(--accent)]" aria-hidden="true" /> {title}
          </p>
          <p className="text-sm text-[var(--text-muted)] mt-0.5">{description}</p>
        </div>
        <button type="button" onClick={onRun} disabled={busy} className={state.status === "done" ? "btn-secondary shrink-0" : "btn-primary shrink-0"} aria-describedby={undefined}>
          {busy ? <Loader2 className="h-4 w-4 animate-spin" aria-hidden="true" /> : state.status === "done" ? <RefreshCw className="h-4 w-4" aria-hidden="true" /> : <Sparkles className="h-4 w-4" aria-hidden="true" />}
          {busy ? "Generating…" : state.status === "done" ? "Regenerate" : "Generate"}
        </button>
      </div>

      <div aria-live="polite" className="text-sm">
        {busy && <p className="text-[var(--text-muted)]">Reading the latest price and fundamentals, then writing the analysis. This usually takes a few seconds.</p>}
        {state.status === "limited" && (
          <p className="flex gap-2 text-amber-200"><Hourglass className="h-4 w-4 mt-0.5 shrink-0" aria-hidden="true" />{state.message || "You've used today's free analyses. Please try again later, or sign in for a higher limit."}</p>
        )}
        {state.status === "error" && (
          <p className="flex gap-2 text-rose-200"><Info className="h-4 w-4 mt-0.5 shrink-0" aria-hidden="true" />{state.message || "The analysis could not be generated."} Press Generate to try again.</p>
        )}
        {state.status === "done" && (
          <p className="text-xs text-[var(--text-subtle)]">
            {state.engine === "Gemini" ? "Generated by AI (Google Gemini)" : "Generated by rule-based fallback (AI model not configured on this server)"}
            {state.at ? ` · ${state.at}` : ""} · Not investment advice.
          </p>
        )}
      </div>

      <details className="text-xs text-[var(--text-subtle)]">
        <summary className="cursor-pointer select-none">Data this analysis uses</summary>
        <p className="mt-1">{dataUsed.join(", ")}.</p>
      </details>
    </div>
  );
}

/** Interprets an AI endpoint response into a run state (429 / quota errors become a kind "limited" message). */
export async function interpretAiResponse(res: Response): Promise<{ state: AiRunState; data: any | null }> {
  let body: any = null;
  try { body = await res.json(); } catch { /* non-JSON */ }
  const at = new Date().toLocaleTimeString("en-GB", { timeZone: "Asia/Dhaka", hour: "numeric", minute: "2-digit", hour12: true }) + " Dhaka time";
  if (res.status === 429 || body?.error === "LIMIT_EXCEEDED" || body?.error === "ANONYMOUS_RATE_LIMIT_EXCEEDED" || body?.error === "ANONYMOUS_DAILY_LIMIT_EXCEEDED") {
    const mins = body?.retryAfterSeconds ? Math.ceil(body.retryAfterSeconds / 60) : null;
    return {
      state: {
        status: "limited",
        message: `You've used the free AI analyses for now${mins ? ` — try again in about ${mins} minute${mins === 1 ? "" : "s"}` : ""}. Signed-in accounts get a higher daily limit.`
      },
      data: null
    };
  }
  if (!res.ok || !body) {
    return { state: { status: "error", message: `The server returned an error (${res.status}).` }, data: null };
  }
  const engine = body?.aiStatus?.mode === "RuleBasedFallback" || /fallback|rule/i.test(String(body?.generationMode || "")) ? "Rule-based" : "Gemini";
  return { state: { status: "done", engine, at }, data: body };
}
